import math

def solve_a4(a3):
    # We are solving for a4 in the equation:
    # (a3-1)/a3 * (a4-1)/a4 = 7/264
    # This simplifies to: a4 = 264*(a3-1) / (257*a3 - 264)

    numerator = 264 * (a3 - 1)
    denominator = 257 * a3 - 264

    if denominator == 0:
        return None

    a4_float = numerator / denominator
    a4 = round(a4_float)

    # Check if a4 is an integer
    if abs(a4_float - a4) < 1e-9:
        # Check constraints
        if a4 > 1 and a4 != a3:
            return a4
        else:
            return None
    return None

# Search for a3 starting from 2
a3_limit = 100
solutions = []

for a3 in range(2, a3_limit + 1):
    if a3 == 5 or a3 == 67:
        continue

    a4 = solve_a4(a3)

    if a4 is not None:
        # Ensure a3 and a4 are distinct
        if a4 != a3:
            solutions.append((min(a3, a4), max(a3, a4)))

print(f"Found solutions (a3, a4) for m=4 with a1=5, a2=67:")
if solutions:
    for sol in solutions:
        print(f"({sol[0]}, {sol[1]})")
else:
    print("No solutions found in the range a3 <= 100.")

